"<body><div class=\"shell\"><aside class=\"sidebar\"><div class=\"brand\"><span class=\"brand-mark\" aria-hidden=\"true\">C6</span><div><strong>灵犀小屏幕</strong><small>240 × 240 · 设备控制台</small></div></div><nav aria-label=\"设备设置\"><a href=\"/\" aria-current=\"page\">Wi-Fi 连接</a><a href=\"/standalone#pairing\">连接与配对</a><a href=\"/standalone#display\">显示与轮转</a><a href=\"/standalone#home\">Home Assistant</a><a href=\"/standalone#bambu\">Bambu Lab</a><a href=\"/standalone#weatherSection\">天气</a></nav><p class=\"sidebar-note\">网络信息保存在这台设备中。<br>无需一直连接电脑，卡片仍可独立运行。</p></aside>\n"
"<main class=\"workspace\"><header class=\"page-heading\"><div><h1>Wi-Fi 连接</h1><p>将 C6 连接到你的局域网，随后在多屏灵犀中扫描添加。</p></div><span class=\"tag\">仅支持 2.4 GHz</span></header>\n"
"<section class=\"card stats\" aria-label=\"连接信息\"><div class=\"stat\"><small>设备地址</small><strong id=\"deviceIP\">正在读取…</strong></div><div class=\"stat\"><small>固件</small><strong id=\"firmware\">—</strong></div><div class=\"stat\"><small>连接状态</small><strong id=\"connectionState\">正在检查</strong></div></section>\n"
"<section class=\"card\"><div class=\"card-heading\"><h2>选择网络</h2><button id=\"scan\" type=\"button\">扫描附近 Wi-Fi</button></div><p class=\"hint\">扫描只显示 C6 支持的 2.4 GHz 网络。隐藏网络可以手动填写；双频同名网络需确保路由器启用了 2.4 GHz。</p><div id=\"scanStatus\" class=\"hint\" role=\"status\" aria-live=\"polite\">尚未扫描。</div><div id=\"networks\" class=\"network-list\" aria-label=\"可用的 2.4 GHz 网络\"></div></section>\n"
"<section class=\"card\"><h2>连接设置</h2><form id=\"wifiForm\" method=\"post\" action=\"/wifi\" autocomplete=\"off\"><div class=\"grid\"><label class=\"field wide\"><span>Wi-Fi 名称（SSID）</span><input id=\"ssid\" name=\"ssid\" type=\"text\" required autocomplete=\"off\" spellcheck=\"false\" placeholder=\"选择上方网络，或手动填写\" aria-describedby=\"networkLimit\"></label><label class=\"field wide\"><span>Wi-Fi 密码</span><input id=\"password\" name=\"password\" type=\"password\" autocomplete=\"new-password\" placeholder=\"开放网络可以留空\"><small>密码不会回显，发送后即清空，不保存到浏览器。</small></label></div><p id=\"networkLimit\" class=\"note\">仅支持 2.4 GHz；无法连接仅有 5 GHz 或 6 GHz 的 Wi-Fi。SSID 区分大小写，不需要修改电脑当前网络。</p><div class=\"actions\"><button id=\"connect\" class=\"primary\" type=\"submit\">保存并连接</button><button id=\"refresh\" type=\"button\">检查连接状态</button></div></form><div id=\"status\" class=\"status\" role=\"status\" aria-live=\"polite\" aria-atomic=\"true\">填写网络名称和密码后，保存到这台 C6。</div></section>\n"
"<section class=\"card\"><h2>联网后的下一步</h2><p class=\"hint\">联网成功后设备屏幕显示局域网 IP，并自动关闭无密码配置热点。手机切回同一 Wi-Fi，再访问屏幕显示的地址；也可回到多屏灵犀的设备管理扫描添加 C6。实体、打印机与天气选择会自动同步到设备。</p><div class=\"actions\"><a href=\"/standalone\">配置独立运行卡片 →</a></div><details class=\"help\"><summary>无法连接时怎么办？</summary><p>先检查密码和路由器的 2.4 GHz 频段。如果未获取地址，可继续连接 Lingxi-C6 热点重试，或在 Mac 的 USB 刷机入口重新预配置 Wi-Fi。</p></details></section>\n"
"<footer class=\"footer\">灵犀 C6 · Waveshare ESP32-C6-LCD-1.3 实验固件<br>首次配置热点无需密码，联网成功后自动关闭。仅在可信环境使用。网络凭据由设备保存，网页不会读取或回显密码。</footer></main></div>\n"
"<script>\n"
"'use strict';const el=id=>document.getElementById(id),bytes=value=>new TextEncoder().encode(value).length;let connecting=false,scanning=false,scanTimer=null,connectionTimer=null,alive=true;\n"
"function message(text,tone=''){el('status').textContent=text;el('status').dataset.tone=tone;}\n"
"async function request(url,options={}){const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),12000);try{return await fetch(url,{cache:'no-store',...options,signal:controller.signal});}catch(e){throw Error(e.name==='AbortError'?'连接超时，请检查设备网络后重试':'无法连接设备，请保持连接到 C6 热点或同一局域网');}finally{clearTimeout(timer);}}\n"
"function setBusy(value){connecting=value;el('connect').disabled=value;el('ssid').disabled=value;el('password').disabled=value;el('scan').disabled=value||scanning;for(const button of el('networks').querySelectorAll('button'))button.disabled=value;}\n"
"async function refreshInfo(){try{const r=await request('/api/info');if(!r.ok)throw Error('状态不可读取');const info=await r.json();if(!alive)return false;const online=info.ip&&info.ip!=='0.0.0.0';el('deviceIP').textContent=online?info.ip:'热点连接 · 等待联网';el('firmware').textContent=info.fw||'C6 测试固件';el('connectionState').textContent=online?'已连接局域网':'尚未获取局域网地址';return !!online;}catch{if(alive){el('connectionState').textContent='暂不可读取 · 可重试';el('deviceIP').textContent='请检查当前网络';}return false;}}\n"
"async function connect(event){event?.preventDefault();if(connecting)return;const ssid=el('ssid').value,password=el('password').value;if(!bytes(ssid)||bytes(ssid)>32||ssid.includes('\\0')){message('请输入 1–32 个 UTF-8 字节的 SSID；中文名称按实际字节长度计算。','error');el('ssid').focus();return;}if(password.includes('\\0')||!(password.length===0||(bytes(password)>=8&&bytes(password)<=63)||(bytes(password)===64&&/^[0-9a-f]{64}$/i.test(password)))){message('密码可留空，或填写 8–63 个 UTF-8 字节；64 位密码须为十六进制 PSK。','error');el('password').focus();return;}setBusy(true);message('正在将网络设置保存到 C6…');try{const r=await request('/wifi',{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},body:new URLSearchParams({ssid,password}).toString()});if(!r.ok)throw Error(r.status===400?'设备拒绝网络信息，请检查 SSID 与密码长度':'网络设置未保存，请稍后重试');el('password').value='';message('网络设置已保存，正在等待设备获取局域网 IP。热点会自动关闭，请切回你的 Wi-Fi，按设备屏幕显示的局域网 IP 打开配置网页。','success');let remaining=10;const poll=async()=>{if(!alive)return;if(await refreshInfo()){message('设备已连接局域网。现在可在多屏灵犀中扫描添加，或打开独立运行配置。','success');return;}if(--remaining>0)connectionTimer=setTimeout(poll,3000);else message('设置已保存，但尚未确认联网。检查密码和 2.4 GHz 频段后重试；若热点已断开，请在软件中重新扫描。');};if(connectionTimer)clearTimeout(connectionTimer);connectionTimer=setTimeout(poll,3000);}catch(e){message(e.message,'error');}finally{setBusy(false);}}\n"
"function showNetworks(networks){el('networks').replaceChildren();for(const network of networks){if(typeof network.ssid!=='string'||!network.ssid)continue;const button=document.createElement('button');button.type='button';const name=document.createElement('span');name.textContent=network.ssid;const signal=document.createElement('small');signal.textContent=(network.open?'开放 · ':'')+(network.rssi>=-55?'信号强':network.rssi>=-75?'信号良好':'信号较弱');button.append(name,signal);button.onclick=()=>{if(el('ssid').value!==network.ssid)el('password').value='';el('ssid').value=network.ssid;for(const item of el('networks').querySelectorAll('button'))item.removeAttribute('aria-pressed');button.setAttribute('aria-pressed','true');el('password').focus();message('已选择网络。填写密码后点击“保存并连接”。');};el('networks').append(button);}}\n"
"async function scan(){if(scanning||connecting)return;scanning=true;el('scan').disabled=true;el('scanStatus').textContent='正在扫描附近的 2.4 GHz 网络…';let remaining=20;const poll=async start=>{try{const r=await request('/api/wifi/scan'+(start?'?start=1':''));if(!r.ok)throw Error(r.status===404?'此固件暂不支持网页扫描。可手动填写 SSID，或在 Mac 的 USB 刷机入口扫描网络。':'扫描未完成，请稍后重试或手动填写 SSID。');const result=await r.json();if(!alive)return;if(result.busy){if(--remaining<=0)throw Error('扫描超时，请稍后重试或手动填写 SSID。');scanTimer=setTimeout(()=>poll(false),500);return;}if(result.error)throw Error(result.message||'设备暂无法扫描，可能正在联网。请稍后重试，或手动填写 SSID。');showNetworks(result.networks||[]);el('scanStatus').textContent=result.networks?.length?'找到 '+result.networks.length+' 个网络；选择一个，或手动填写隐藏网络。':'没有发现可用网络。请检查路由器 2.4 GHz 频段，或手动填写 SSID。';}catch(e){el('scanStatus').textContent=e.message;}scanning=false;el('scan').disabled=connecting;};await poll(true);}\n"
"el('wifiForm').onsubmit=connect;el('scan').onclick=scan;el('refresh').onclick=refreshInfo;el('ssid').oninput=()=>{el('password').value='';};window.addEventListener('pagehide',()=>{alive=false;el('password').value='';clearTimeout(scanTimer);clearTimeout(connectionTimer);});refreshInfo();\n"
"</script></body></html>\n"
"\n";
